import React, { useState } from "react";
import { useNavigate } from "react-router-dom";
import "../styles/signIn.css"; 

function SignUp() {
  const navigate = useNavigate();

  const [name, setName] = useState("");
  const [email, setEmail] = useState("");
  const [phone, setPhone] = useState("");
  const [password, setPassword] = useState("");

  const handleSubmit = (e) => {
    e.preventDefault();

    const trimmedName = name.trim();
    const trimmedEmail = email.trim();
    const trimmedPhone = phone.trim();
    const trimmedPassword = password.trim();

    let users = JSON.parse(localStorage.getItem("users") || "[]");

    if (users.some(u => u.email === trimmedEmail)) {
      alert("Email already registered!");
      return;
    }

    users.push({ name: trimmedName, email: trimmedEmail, phone: trimmedPhone, password: trimmedPassword });
    localStorage.setItem("users", JSON.stringify(users));
    alert("✅ Registration successful! Returning to main page.");
    navigate("/"); // redireciona para a página principal ou login
  };

  return (
    <div className="signup-container">
      <a href="/" id="companyName">Bella Nails Studio</a>
      <h1>Sign Up</h1>

      <form onSubmit={handleSubmit}>
        <input
          type="text"
          placeholder="Name"
          value={name}
          onChange={(e) => setName(e.target.value)}
          required
        />
        <input
          type="email"
          placeholder="Email"
          value={email}
          onChange={(e) => setEmail(e.target.value)}
          required
        />
        <input
          type="text"
          placeholder="Phone"
          value={phone}
          onChange={(e) => setPhone(e.target.value)}
          required
        />
        <input
          type="password"
          placeholder="Password"
          value={password}
          onChange={(e) => setPassword(e.target.value)}
          required
        />
        <button type="submit">Register</button>
      </form>

      <p>
        Already have an account? <a href="/signin">Sign In</a>
      </p>
    </div>
  );
}

export default SignUp;
